:- module(m__ch_swiss_fadp_s3_right_of_access_citations, [citation/2, implements/1]).
:- use_module(library(lists)).
:- use_module(library(iso_ext)).
:- use_module(library(between)).
:- use_module(library(dif)).

citation(ch_fadp_art_25_1, [label - 'DSG (SR 235.1) Art 25 Abs 1 (right of access)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_25/para_1', verbatim - 'Jede Person kann vom Verantwortlichen Auskunft dar\xFC\ber verlangen, ob Personendaten \xFC\ber sie bearbeitet werden.']).
citation(ch_fadp_art_25_6, [label - 'DSG (SR 235.1) Art 25 Abs 6 (access free of charge; exceptions by the Federal Council)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_25/para_6', verbatim - 'Der Verantwortliche muss kostenlos Auskunft erteilen. Der Bundesrat kann Ausnahmen vorsehen, namentlich wenn der Aufwand unverh\xE4\ltnism\xE4\ssig ist.']).
citation(ch_fadp_art_25_7, [label - 'DSG (SR 235.1) Art 25 Abs 7 (as a rule within 30 days)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_25/para_7', verbatim - 'Die Auskunft wird in der Regel innerhalb von 30 Tagen erteilt.']).
citation(ch_fadp_art_26_1, [label - 'DSG (SR 235.1) Art 26 Abs 1, lead-in (controller may refuse, restrict or defer)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_26/para_1/listintro', verbatim - 'Der Verantwortliche kann die Auskunft verweigern, einschr\xE4\nken oder aufschieben, wenn:']).
citation(ch_fadp_art_26_1_a, [label - 'DSG (SR 235.1) Art 26 Abs 1 Bst a (a law in the formal sense provides for it)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_26/para_1/lbl_a', verbatim - 'ein Gesetz im formellen Sinn dies vorsieht, namentlich um ein Berufsgeheimnis zu sch\xFC\tzen;']).
citation(ch_fadp_art_26_1_b, [label - 'DSG (SR 235.1) Art 26 Abs 1 Bst b (overriding interests of third parties)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_26/para_1/lbl_b', verbatim - 'dies aufgrund \xFC\berwiegender Interessen Dritter erforderlich ist; oder']).
citation(ch_fadp_art_26_1_c, [label - 'DSG (SR 235.1) Art 26 Abs 1 Bst c (request manifestly unfounded or manifestly querulous)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_26/para_1/lbl_c', verbatim - 'das Auskunftsgesuch offensichtlich unbegr\xFC\ndet ist, namentlich wenn es einen datenschutzwidrigen Zweck verfolgt, oder offensichtlich querulatorisch ist.']).
citation(ch_fadp_art_26_2, [label - 'DSG (SR 235.1) Art 26 Abs 2, lead-in (further cases, in addition)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_26/para_2/listintro', verbatim - 'Dar\xFC\ber hinaus ist es in den folgenden F\xE4\llen m\xF6\glich, die Auskunft zu verweigern, einzuschr\xE4\nken oder aufzuschieben:']).
citation(ch_fadp_art_26_2_a, [label - 'DSG (SR 235.1) Art 26 Abs 2 Bst a, lead-in (controller a private person, both conditions met)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_26/para_2/lbl_a/listintro', verbatim - 'Der Verantwortliche ist eine private Person und die folgenden Voraussetzungen sind erf\xFC\llt:']).
citation(ch_fadp_art_26_2_a_1, [label - 'DSG (SR 235.1) Art 26 Abs 2 Bst a Ziff 1 (overriding interests of the controller)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_26/para_2/lbl_a/lbl_1', verbatim - '\xDC\berwiegende Interessen des Verantwortlichen erfordern die Massnahme.']).
citation(ch_fadp_art_26_2_a_2, [label - 'DSG (SR 235.1) Art 26 Abs 2 Bst a Ziff 2 (no disclosure to third parties)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_26/para_2/lbl_a/lbl_2', verbatim - 'Der Verantwortliche gibt die Personendaten nicht Dritten bekannt.']).
citation(ch_fadp_art_26_2_b, [label - 'DSG (SR 235.1) Art 26 Abs 2 Bst b, lead-in (controller a federal body, one condition met)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_26/para_2/lbl_b/listintro', verbatim - 'Der Verantwortliche ist ein Bundesorgan, und eine der folgenden Voraussetzungen ist erf\xFC\llt:']).
citation(ch_fadp_art_26_2_b_1, [label - 'DSG (SR 235.1) Art 26 Abs 2 Bst b Ziff 1 (overriding public interests)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_26/para_2/lbl_b/lbl_1', verbatim - 'Die Massnahme ist wegen \xFC\berwiegender \xF6\ffentlicher Interessen, insbesondere der inneren oder der \xE4\usseren Sicherheit der Schweiz, erforderlich.']).
citation(ch_fadp_art_26_2_b_2, [label - 'DSG (SR 235.1) Art 26 Abs 2 Bst b Ziff 2 (danger to an investigation, inquiry or proceedings)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_26/para_2/lbl_b/lbl_2', verbatim - 'Die Mitteilung der Information kann eine Ermittlung, eine Untersuchung oder ein beh\xF6\rdliches oder gerichtliches Verfahren gef\xE4\hrden.']).
citation(ch_fadp_art_26_3, [label - 'DSG (SR 235.1) Art 26 Abs 3 (undertakings of the same group are not third parties)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_26/para_3', verbatim - 'Unternehmen, die zum selben Konzern geh\xF6\ren, gelten nicht als Dritte im Sinne von Absatz 2 Buchstabe a Ziffer 2.']).
citation(ch_fadp_art_26_4, [label - 'DSG (SR 235.1) Art 26 Abs 4 (controller must state reasons)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_26/para_4', verbatim - 'Der Verantwortliche muss angeben, weshalb er die Auskunft verweigert, einschr\xE4\nkt oder aufschiebt.']).
citation(ch_fadp_art_27_1, [label - 'DSG (SR 235.1) Art 27 Abs 1, lead-in (data processed exclusively for the editorial part of a periodical medium)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_27/para_1/listintro', verbatim - 'Werden Personendaten ausschliesslich zur Ver\xF6\ffentlichung im redaktionellen Teil eines periodisch erscheinenden Mediums bearbeitet, so kann der Verantwortliche aus einem der folgenden Gr\xFC\nde die Auskunft verweigern, einschr\xE4\nken oder aufschieben:']).
citation(ch_fadp_art_27_1_a, [label - 'DSG (SR 235.1) Art 27 Abs 1 Bst a (data reveal the sources of information)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_27/para_1/lbl_a', verbatim - 'Die Daten geben Aufschluss \xFC\ber die Informationsquellen.']).
citation(ch_fadp_art_27_1_b, [label - 'DSG (SR 235.1) Art 27 Abs 1 Bst b (insight into drafts for publications)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_27/para_1/lbl_b', verbatim - 'Durch die Auskunft w\xFC\rde Einsicht in Entw\xFC\rfe f\xFC\r Publikationen gew\xE4\hrt.']).
citation(ch_fadp_art_27_1_c, [label - 'DSG (SR 235.1) Art 27 Abs 1 Bst c (free formation of public opinion endangered)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_27/para_1/lbl_c', verbatim - 'Die Ver\xF6\ffentlichung w\xFC\rde die freie Meinungsbildung des Publikums gef\xE4\hrden.']).
citation(ch_fadp_art_27_2, [label - 'DSG (SR 235.1) Art 27 Abs 2 (media professionals: personal working instrument)', ref - 'ch-fadp-sr-235-1-2025-07-07#art_27/para_2', verbatim - 'Medienschaffende k\xF6\nnen die Auskunft zudem verweigern, einschr\xE4\nken oder aufschieben, wenn ihnen die Personendaten ausschliesslich als pers\xF6\nliches Arbeitsinstrument dienen.']).
citation(ch_fadp_ord_art_16_1, [label - 'DSV (SR 235.11) Art 16 Abs 1 (request in writing; orally if the controller agrees)', ref - 'ch-fadp-ord-sr-235-11-2025-12-01#art_16/para_1', verbatim - 'Wer vom Verantwortlichen Auskunft dar\xFC\ber verlangt, ob Personendaten \xFC\ber sie oder ihn bearbeitet werden, muss dies schriftlich tun. Ist der Verantwortliche einverstanden, so kann das Begehren auch m\xFC\ndlich mitgeteilt werden.']).
citation(ch_fadp_ord_art_16_3, [label - 'DSV (SR 235.11) Art 16 Abs 3 (electronic means)', ref - 'ch-fadp-ord-sr-235-11-2025-12-01#art_16/para_3', verbatim - 'Das Auskunftsbegehren und die Auskunftserteilung k\xF6\nnen auf elektronischem Weg erfolgen.']).
citation(ch_fadp_ord_art_18_1, [label - 'DSV (SR 235.11) Art 18 Abs 1 (30 days of receipt of the request)', ref - 'ch-fadp-ord-sr-235-11-2025-12-01#art_18/para_1', verbatim - 'Die Auskunft muss innerhalb von 30 Tagen seit dem Eingang des Begehrens erteilt werden.']).
citation(ch_fadp_ord_art_18_3, [label - 'DSV (SR 235.11) Art 18 Abs 3 (refusal, restriction or deferral within the same period)', ref - 'ch-fadp-ord-sr-235-11-2025-12-01#art_18/para_3', verbatim - 'Verweigert der Verantwortliche die Auskunft, schr\xE4\nkt er sie ein oder schiebt er sie auf, so muss er dies innerhalb derselben Frist mitteilen.']).
citation(ch_fadp_ord_art_19_1, [label - 'DSV (SR 235.11) Art 19 Abs 1 (disproportionate effort: appropriate cost contribution)', ref - 'ch-fadp-ord-sr-235-11-2025-12-01#art_19/para_1', verbatim - 'Ist die Erteilung der Auskunft mit einem unverh\xE4\ltnism\xE4\ssigen Aufwand verbunden, so kann der Verantwortliche von der betroffenen Person verlangen, dass sie sich an den Kosten angemessen beteiligt.']).
citation(ch_fadp_ord_art_19_2, [label - 'DSV (SR 235.11) Art 19 Abs 2 (contribution at most 300 francs)', ref - 'ch-fadp-ord-sr-235-11-2025-12-01#art_19/para_2', verbatim - 'Die Beteiligung betr\xE4\gt maximal 300 Franken.']).
citation(ch_fadp_ord_art_19_3, [label - 'DSV (SR 235.11) Art 19 Abs 3 (notice of the amount; ten-day period for reflection; time limit runs after it)', ref - 'ch-fadp-ord-sr-235-11-2025-12-01#art_19/para_3', verbatim - 'Die Frist nach Artikel 18 Absatz 1 beginnt nach Ablauf der zehnt\xE4\gigen Bedenkzeit zu laufen.']).
citation(eu_reg_2016_679_art_12_3, [label - 'Regulation (EU) 2016/679 Art 12(3) (information on action taken within one month of receipt)', ref - '02016R0679-20160504#parag_012.003', verbatim - 'The controller shall provide information on action taken on a request under Articles 15 to 22 to the data subject without undue delay and in any event within one month of receipt of the request.']).
citation(eu_reg_1971_1182_art_3_1, [label - 'Regulation (EEC, Euratom) No 1182/71 Art 3(1), second sentence (day of the event not counted)', ref - '31971R1182#parag_003.001', verbatim - 'Where a period expressed in days, weeks, months or years is to be calculated from the moment at which an event occurs or an action takes place, the day during which that event occurs or that action takes place shall not be considered as falling within the period in question.']).
citation(eu_reg_1971_1182_art_3_2_c, [label - 'Regulation (EEC, Euratom) No 1182/71 Art 3(2)(c) (end of a period expressed in months)', ref - '31971R1182#point_003.002_c', verbatim - 'If, in a period expressed in months or in years, the day on which it should expire does not occur in the last month, the period shall end with the expiry of the last hour of the last day of that month;']).
citation(eu_reg_1971_1182_art_3_4, [label - 'Regulation (EEC, Euratom) No 1182/71 Art 3(4) (last day a Saturday, Sunday or public holiday)', ref - '31971R1182#parag_003.004', verbatim - 'Where the last day of a period expressed otherwise than in hours is a public holiday, Sunday or Saturday, the period shall end with the expiry of the last hour of the following working day.']).

implements(Key) :-
    citation(Key, _).
